package dev.myjarvis.core;

import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;

/** Synthetic provenance, causal ordering, and durable revocation checks; no model invocation. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class InferenceContextServiceTest {
    EmbeddedPostgres postgres;ConfigurableApplicationContext app;JdbcTemplate db;Path key;
    AuthService auth;WorkflowService flow;Vault vault;InferenceContextService contexts;InferenceContextFreshness freshness;
    AuthService.Session session;UUID owner,conversation;
    @BeforeAll void start()throws Exception{postgres=EmbeddedPostgres.builder().setPort(0).start();key=Files.createTempFile("context-test-",".bin");byte[] bytes=new byte[32];Vault.RNG.nextBytes(bytes);Files.write(key,bytes);Files.setPosixFilePermissions(key,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));open();}
    void open(){app=new SpringApplicationBuilder(CoreApplication.class).web(WebApplicationType.NONE).run("--spring.datasource.url="+postgres.getJdbcUrl("postgres","postgres"),"--spring.datasource.username=postgres","--spring.datasource.password=","--jarvis.key-file="+key,"--jarvis.mode=mock","--jarvis.worker.enabled=false","--spring.main.banner-mode=off");db=app.getBean(JdbcTemplate.class);auth=app.getBean(AuthService.class);flow=app.getBean(WorkflowService.class);vault=app.getBean(Vault.class);contexts=app.getBean(InferenceContextService.class);freshness=app.getBean(InferenceContextFreshness.class);}
    @AfterAll void stop()throws Exception{if(app!=null)app.close();if(postgres!=null)postgres.close();if(key!=null)Files.deleteIfExists(key);}
    @BeforeEach void reset(){db.execute("TRUNCATE owners,bootstrap_tokens,login_limits,crypto_nonces CASCADE");owner=UUID.randomUUID();db.update("INSERT INTO owners(id,login_name,password_hash) VALUES (?,'context-owner','synthetic')",owner);session=auth.find(auth.issue(owner,true,null).token());conversation=UUID.randomUUID();db.update("INSERT INTO conversations(id,owner_id,title) VALUES (?,?,'Synthetic')",conversation,owner);}
    UUID run(String status){UUID id=UUID.randomUUID();db.update("INSERT INTO runs(id,owner_id,conversation_id,status,history_epoch) SELECT ?,?,?,?,history_epoch FROM owners WHERE id=?",id,owner,conversation,status,owner);return id;}
    void message(UUID run,String role,String text){UUID id=UUID.randomUUID();db.update("INSERT INTO messages(id,owner_id,conversation_id,run_id,client_message_id,body_hash,content_ref,role,trust) VALUES (?,?,?,?,?,?,?,?,?)",id,owner,conversation,run,role.equals("USER")?UUID.randomUUID():null,Json.hash(text),vault.seal(owner,id,"message",text),role,role.equals("USER")?"USER_DIRECT":"MODEL_PROPOSAL");}
    UUID pair(String status,String text){UUID id=run(status);message(id,"USER","Question "+text);message(id,"ASSISTANT","Reply "+text);return id;}
    UUID capture(){UUID run=run("QUEUED");message(run,"USER","Current question");flow.tx.executeWithoutResult(tx->contexts.capture(session,conversation,run));return run;}
    Map<String,Object> prepare(UUID run){return flow.tx.execute(tx->contexts.prepare(owner,run));}
    boolean valid(UUID run){return Boolean.TRUE.equals(flow.tx.execute(tx->freshness.valid(owner,run)));}
    @SuppressWarnings("unchecked") List<Map<String,Object>> list(Map<String,Object> data,String field){return (List<Map<String,Object>>)data.get(field);}
    UUID memory(UUID project,String key,String value){UUID slot=UUID.randomUUID(),id=UUID.randomUUID();String digest=app.getBean(MemoryKeyCodec.class).slot(owner,key);db.update("INSERT INTO memory_slots(id,owner_id,scope,project_id,key_digest,generation) VALUES (?,?,?,?,?,1)",slot,owner,project==null?"GLOBAL":"PROJECT",project,digest);db.update("INSERT INTO memories(id,owner_id,slot_id,kind,generation,version,payload_ref,confirmed_at) VALUES (?,?,?,'PREFERENCE',1,1,?,clock_timestamp())",id,owner,slot,vault.seal(owner,id,"memory-current",Json.canonical(Map.of("key",key,"value",value))));db.update("UPDATE memory_slots SET current_memory_id=? WHERE id=?",id,slot);return id;}
    UUID project(){UUID id=UUID.randomUUID();db.update("INSERT INTO projects(id,owner_id,name) VALUES (?,?,'Synthetic project')",id,owner);return id;}
    void reservation(UUID run,String status){db.update("INSERT INTO inference_reservations(id,owner_id,run_id,request_id,body_hash,model_manifest_hash,status,max_compute_ms,reserved_output_tokens,security_epoch) VALUES (?,?,?,?,?,?,?,60000,512,?)",UUID.randomUUID(),owner,run,UUID.randomUUID(),"0".repeat(64),"1".repeat(64),status,session.epoch());}
    @Test void singletonAndTransactionBoundariesRemainEnforced(){assertThrows(Exception.class,()->db.update("INSERT INTO owners(id,login_name,password_hash) VALUES (?,'second','unused')",UUID.randomUUID()));assertThrows(IllegalStateException.class,()->freshness.invalidateOwner(owner,false));assertEquals(1L,db.queryForObject("SELECT count(*) FROM owners",Long.class));}
    @Test void nullProjectSelectsOnlyGlobalAndPersistsNoPlaintext(){UUID project=project();memory(null,"color","Synthetic secret blue");memory(project,"shape","Synthetic square");var data=prepare(capture());assertNull(data.get("project_context"));assertEquals("UTC",data.get("timezone"));assertEquals(1,list(data,"memories").size());assertEquals("Synthetic secret blue",list(data,"memories").getFirst().get("value"));for(String table:List.of("inference_contexts","inference_context_history","inference_context_memories")){String dump=Json.canonical(db.queryForList("SELECT * FROM "+table));assertFalse(dump.contains("Synthetic secret blue"));assertFalse(dump.contains(Json.hash("Synthetic secret blue")));}}
    @Test void overridesAndTombstonesAreAppliedBeforeCap(){UUID project=project();db.update("UPDATE conversations SET project_id=? WHERE id=?",project,conversation);memory(null,"color","Global");UUID override=memory(project,"color","Project");for(int i=0;i<23;i++)memory(null,"key"+i,"Value "+i);var data=prepare(capture());assertEquals(20,list(data,"memories").size());assertEquals(override,list(data,"memories").getFirst().get("id"));assertFalse(list(data,"memories").stream().anyMatch(m->m.get("value").equals("Global")));db.update("UPDATE memory_slots SET current_memory_id=NULL,tombstone=true WHERE current_memory_id=?",override);data=prepare(capture());assertFalse(list(data,"memories").stream().anyMatch(m->m.get("key").equals("color")));}
    @Test void causalAnchorExcludesLaterCompletionsAndKeepsAcceptedPairs(){for(int i=0;i<10;i++)pair(i==9?"WAITING_INPUT":"SUCCEEDED","prior"+i);UUID pending=pair("RUNNING","pending");UUID current=capture();db.update("UPDATE runs SET status='SUCCEEDED' WHERE id=?",pending);pair("SUCCEEDED","future");for(String status:List.of("FAILED","UNKNOWN","CANCELLED"))pair(status,status);var history=list(prepare(current),"history");assertEquals(16,history.size());assertEquals("Question prior2",history.getFirst().get("text"));assertEquals("Reply prior9",history.getLast().get("text"));for(int i=0;i<16;i+=2){assertEquals("USER",history.get(i).get("role"));assertEquals("ASSISTANT",history.get(i+1).get("role"));assertEquals(history.get(i).get("run_id"),history.get(i+1).get("run_id"));}}
    @Test void duplicateAssistantCannotExistAndResultRefIsNotAnExtraReply(){UUID past=pair("SUCCEEDED","accepted");assertThrows(Exception.class,()->message(past,"ASSISTANT","duplicate"));db.update("UPDATE runs SET result_ref=? WHERE id=?",vault.seal(owner,past,"result","Unused duplicate result"),past);assertEquals(2,list(prepare(capture()),"history").size());}
    @Test void legacyAndOtherConversationHistoryIsNotInjected(){UUID legacy=pair("SUCCEEDED","legacy");db.update("UPDATE runs SET context_history_eligible=false WHERE id=?",legacy);UUID other=conversation;conversation=UUID.randomUUID();db.update("INSERT INTO conversations(id,owner_id,title) VALUES (?,?,'Other')",conversation,owner);pair("SUCCEEDED","other");conversation=other;assertTrue(list(prepare(capture()),"history").isEmpty());}
    @Test void authorizationAndInactiveProjectFailBeforeBadCiphertext(){memory(null,"key","value");db.update("UPDATE memories SET payload_ref='unreadable'");var foreign=new AuthService.Session(session.hash(),UUID.randomUUID(),null,session.epoch());ApiException error=assertThrows(ApiException.class,()->flow.tx.executeWithoutResult(tx->contexts.capture(foreign,conversation,UUID.randomUUID())));assertEquals("SESSION_REVOKED",error.code);UUID project=project();db.update("UPDATE projects SET active=false WHERE id=?",project);db.update("UPDATE conversations SET project_id=? WHERE id=?",project,conversation);assertThrows(ApiException.class,this::capture);}
    @Test void rotationExpiryAndRestartRemainRevoked(){UUID run=capture();prepare(run);auth.issue(owner,true,session.hash());assertFalse(valid(run));app.close();open();assertFalse(valid(run));session=auth.find(auth.issue(owner,true,null).token());UUID next=capture();db.update("UPDATE sessions SET last_seen_at=clock_timestamp()-interval '3 hours' WHERE token_hash=?",session.hash());assertFalse(valid(next));}
    @Test void deletionInvalidatesQueuedAndDropsPriorEpochHistory(){pair("SUCCEEDED","old");UUID queued=capture();reservation(queued,"QUEUED");flow.tx.executeWithoutResult(tx->freshness.invalidateOwner(owner,true));assertFalse(valid(queued));assertEquals("CANCELLED",db.queryForObject("SELECT status FROM inference_reservations WHERE run_id=?",String.class,queued));assertTrue(list(prepare(capture()),"history").isEmpty());assertEquals(3L,db.queryForObject("SELECT count(*) FROM messages WHERE role='USER'",Long.class));}
    @Test void startedDeletionRetainsFullUnknownReservationAndRejectsLateSettlement(){UUID run=capture();prepare(run);flow.tx.executeWithoutResult(tx->contexts.markDispatched(owner,run));reservation(run,"STARTED");db.update("UPDATE runs SET status='RUNNING' WHERE id=?",run);flow.tx.executeWithoutResult(tx->freshness.invalidateOwner(owner,true));assertFalse(valid(run));assertEquals("UNKNOWN",db.queryForObject("SELECT status FROM inference_reservations WHERE run_id=?",String.class,run));assertEquals(60000L,db.queryForObject("SELECT max_compute_ms FROM inference_reservations WHERE run_id=?",Long.class,run));assertThrows(ApiException.class,()->flow.tx.executeWithoutResult(tx->contexts.markSettled(owner,run)));}
    @Test void mutationRollbackRestoresEpochAndContext(){UUID run=capture();prepare(run);long epoch=db.queryForObject("SELECT context_epoch FROM owners",Long.class);assertThrows(IllegalStateException.class,()->flow.tx.executeWithoutResult(tx->{freshness.invalidateOwner(owner,true);throw new IllegalStateException("Synthetic rollback");}));assertTrue(valid(run));assertEquals(epoch,db.queryForObject("SELECT context_epoch FROM owners",Long.class));}
    @Test void revisedSourceOrProjectVersionFailsIndependentMetadataGate(){UUID memory=memory(null,"key","value");UUID run=capture();prepare(run);db.update("UPDATE memories SET version=version+1 WHERE id=?",memory);assertFalse(valid(run));UUID project=project();db.update("UPDATE conversations SET project_id=? WHERE id=?",project,conversation);UUID next=capture();prepare(next);db.update("UPDATE projects SET version=version+1 WHERE id=?",project);assertFalse(valid(next));}
    @Test void settledInvalidatedContextCannotReenterHistory(){UUID run=capture();prepare(run);flow.tx.executeWithoutResult(tx->{contexts.markDispatched(owner,run);contexts.markSettled(owner,run);db.update("UPDATE runs SET status='SUCCEEDED' WHERE id=?",run);message(run,"ASSISTANT","Context derived reply");});assertEquals(2,list(prepare(capture()),"history").size());flow.tx.executeWithoutResult(tx->freshness.invalidateOwner(owner,false));assertTrue(list(prepare(capture()),"history").isEmpty());}
    @Test void sessionRevocationStopsActiveContextButRetainsAcceptedHistory(){UUID settled=capture();prepare(settled);flow.tx.executeWithoutResult(tx->{contexts.markDispatched(owner,settled);contexts.markSettled(owner,settled);db.update("UPDATE runs SET status='SUCCEEDED' WHERE id=?",settled);message(settled,"ASSISTANT","Accepted prior answer");});UUID active=capture();reservation(active,"QUEUED");auth.logout(session);assertFalse(valid(active));assertEquals("SETTLED",db.queryForObject("SELECT state FROM inference_contexts WHERE run_id=?",String.class,settled));session=auth.find(auth.issue(owner,true,null).token());var history=list(prepare(capture()),"history");assertEquals(2,history.size());assertEquals("Accepted prior answer",history.getLast().get("text"));}
    @Test void targetedInvalidationDoesNotAdvanceOwnerEpochOrCancelOtherRuns(){UUID first=capture(),second=capture();reservation(first,"QUEUED");reservation(second,"QUEUED");long epoch=db.queryForObject("SELECT context_epoch FROM owners",Long.class);flow.tx.executeWithoutResult(tx->{freshness.invalidateRun(owner,first);freshness.invalidateRun(owner,first);});assertFalse(valid(first));assertTrue(valid(second));assertEquals(epoch,db.queryForObject("SELECT context_epoch FROM owners",Long.class));assertEquals("QUEUED",db.queryForObject("SELECT status FROM inference_reservations WHERE run_id=?",String.class,second));}
    @Test void logoutBlocksSelectionBeforeSourceDecryption(){memory(null,"key","Synthetic value");UUID run=capture();db.update("UPDATE memories SET payload_ref='unreadable'");auth.logout(session);var failure=assertThrows(ApiException.class,()->prepare(run));assertEquals("STALE_INFERENCE_CONTEXT",failure.code);}
    @Test void profileTimezoneIsReadThroughEncryptedOwnerSettings(){var profiles=app.getBean(OwnerProfileService.class);profiles.patch(session,UUID.randomUUID(),Json.MAPPER.valueToTree(Map.of("expected_version",1,"timezone","Asia/Seoul")));var data=prepare(capture());assertEquals("Asia/Seoul",data.get("timezone"));assertEquals(2L,((Map<?,?>)data.get("context")).get("profile_version"));}
    @Test void malformedProfileTimezoneFailsClosed(){db.update("UPDATE owners SET profile_ref=?,profile_updated_at=clock_timestamp() WHERE id=?",vault.seal(owner,owner,"owner-profile",Json.canonical(Map.of("display_name","Synthetic","locale","en-US","timezone","Unknown/Zone"))),owner);UUID run=capture();assertThrows(Exception.class,()->prepare(run));assertEquals("CAPTURED",db.queryForObject("SELECT state FROM inference_contexts WHERE run_id=?",String.class,run));}
    @Test void oversizedHistoryFailsClosedWithoutPartialMetadata(){pair("SUCCEEDED","x".repeat(40000));UUID run=capture();assertThrows(ApiException.class,()->prepare(run));assertEquals("CAPTURED",db.queryForObject("SELECT state FROM inference_contexts WHERE run_id=?",String.class,run));assertEquals(0L,db.queryForObject("SELECT count(*) FROM inference_context_memories",Long.class));}
    @Test void digestIsOwnerBoundAndNotPublicContentHash(){String text="Synthetic low entropy";assertNotEquals(Json.hash(text),contexts.requestDigest(owner,text));assertNotEquals(contexts.requestDigest(owner,text),contexts.requestDigest(UUID.randomUUID(),text));assertEquals(contexts.requestDigest(owner,text),contexts.requestDigest(owner,text));}

    @Test void ownerLockSerializesDeletionAgainstSelection()throws Exception{UUID run=capture();CountDownLatch began=new CountDownLatch(1);try(var pool=Executors.newSingleThreadExecutor()){var future=new java.util.concurrent.atomic.AtomicReference<Future<Boolean>>();flow.tx.executeWithoutResult(tx->{freshness.lock(owner);future.set(pool.submit(()->{began.countDown();return valid(run);}));try{assertTrue(began.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}freshness.invalidateOwner(owner,true);});assertFalse(future.get().get(15,TimeUnit.SECONDS));}}
}
